const $=s=>document.querySelector(s);const types={estudos:['◇','Estudos'],treinos:['⌁','Treinos'],lembretes:['♧','Lembretes'],eventos:['▦','Calendário']};const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'});let items=[];try{items=JSON.parse(localStorage.getItem('meu-espaco-v1')||'[]')}catch{}let page='inicio',filter='todos',month=new Date(),selected=today();const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function save(){localStorage.setItem('meu-espaco-v1',JSON.stringify(items));render()}function add(type){$('#form').reset();$('#form [name=type]').value=type||'lembretes';$('#form [name=date]').value=page==='eventos'?selected:today();$('#formtitle').textContent='Novo item';$('#modal').showModal();$('#form [name=title]').focus()}function row(i){return `<div class="row ${i.done?'done':''}"><input type="checkbox" aria-label="Concluir ${esc(i.title)}" data-done="${i.id}" ${i.done?'checked':''}><div class="body"><b>${esc(i.title)}</b><small>${esc(i.date.split('-').reverse().join('/'))}${i.time?' · '+esc(i.time):''}${i.notes?'\n'+esc(i.notes):''}</small></div><span class="tag">${types[i.type][1]}</span><button class="delete" data-delete="${i.id}" aria-label="Excluir ${esc(i.title)}">×</button></div>`}function empty(type){return `<div class="empty"><span class="symbol">${types[type][0]}</span><strong>Espaço para seus próximos passos</strong><p>${{estudos:'Organize matérias, revisões e sessões de estudo.',treinos:'Registre seus treinos, exercícios e cargas.',lembretes:'Tire da cabeça e coloque aqui.',eventos:'Reserve tempo para o que importa.'}[type]}</p><button data-add="${type}">+ Adicionar ${type==='eventos'?'evento':types[type][1].toLowerCase()}</button></div>`}function panel(title,body,action=''){return `<div class="panel"><div class="panelhead"><h2>${title}</h2>${action}</div>${body}</div>`}function calendar(){let year=month.getFullYear(),m=month.getMonth(),start=new Date(year,m,1).getDay(),end=new Date(year,m+1,0).getDate();let days=Array(start).fill('<span></span>');for(let d=1;d<=end;d++){let key=`${year}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;days.push(`<button class="day ${key===today()?'today':''} ${key===selected?'selected':''} ${items.some(i=>i.date===key)?'has':''}" data-date="${key}" aria-label="${key}" aria-pressed="${key===selected}">${d}</button>`)}return `<div class="calendar"><div class="calbar"><b>${month.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</b><div><button data-month="-1" aria-label="Mês anterior">‹</button> <button data-month="1" aria-label="Próximo mês">›</button></div></div><div class="grid">${['DOM','SEG','TER','QUA','QUI','SEX','SÁB'].map(x=>`<span class="dayname">${x}</span>`).join('')}${days.join('')}</div><div class="datehint">● Hoje &nbsp; · &nbsp; Clique em um dia para ver sua agenda</div></div>`}function render(){let now=new Date();$('#nav').innerHTML=[['inicio','⊞','Visão geral'],...Object.entries(types).map(([k,v])=>[k,...v])].map(([k,i,t])=>`<button data-page="${k}" class="${page===k?'active':''}" ${page===k?'aria-current="page"':''}><span class="navicon">${i}</span>${t}</button>`).join('');$('#breadcrumb').textContent='Meu espaço / '+(page==='inicio'?'Visão geral':types[page][1]);let label=now.toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long',timeZone:'America/Sao_Paulo'});let title=page==='inicio'?'Um pouco de ordem, mais leveza.':types[page][1];let subtitle=page==='inicio'?'Tudo o que importa, em um só lugar.':{estudos:'Dê espaço ao que você quer aprender.',treinos:'Sua rotina de movimento começa aqui.',lembretes:'Menos coisas na cabeça. Mais clareza no dia.',eventos:'Tempo para suas prioridades.'}[page];let html=`<div class="eyebrow">${esc(label)}</div><div class="titlebar"><div><h1>${title}</h1><p>${subtitle}</p></div><button class="primary" data-add="${page==='inicio'?'lembretes':page}">+ Novo item</button></div>`;if(page==='inicio'){let upcoming=items.filter(i=>!i.done&&i.date>=today()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).slice(0,5);html+=`<div class="stats">${Object.entries(types).map(([k,v])=>`<div class="stat"><div class="top">${v[1]}<span>${v[0]}</span></div><strong>${items.filter(i=>i.type===k&&!i.done).length.toString().padStart(2,'0')}</strong><small>${k==='eventos'?'eventos planejados':'itens em andamento'}</small></div>`).join('')}</div><div class="columns"><div>${panel('Próximos passos',upcoming.length?upcoming.map(row).join(''):empty('lembretes'),'<span class="tag">Sua agenda</span>')}${panel('Lembretes',items.filter(i=>i.type==='lembretes'&&!i.done).slice(0,3).map(row).join('')||'<div class="empty"><p>Nenhuma pendência por aqui.<br>Adicione algo para lembrar depois.</p></div>','<button class="textbutton" data-page="lembretes">Ver todos ↗</button>')}</div><div>${panel('Seu calendário',calendar())}<div class="quote"><span class="eyebrow">NO SEU RITMO</span><p>Pequenos passos também levam longe.</p><small>Reserve um momento para você hoje.</small></div></div></div><div class="sectioncaption">ADICIONAR À SUA ROTINA</div><div class="quick">${Object.entries(types).map(([k,v])=>`<button data-add="${k}">${v[0]} &nbsp; ${v[1]} <span>＋</span></button>`).join('')}</div>`}else if(page==='eventos'){html+=`<div class="columns"><div class="fullcalendar">${panel('Planeje seu mês',calendar())}</div><div>${panel('Agenda · '+selected.split('-').reverse().join('/'),items.filter(i=>i.date===selected).sort((a,b)=>a.time.localeCompare(b.time)).map(row).join('')||empty('eventos'))}</div></div>`}else{let list=items.filter(i=>i.type===page&&(filter==='todos'||(filter==='concluidos'?i.done:!i.done))).sort((a,b)=>a.date.localeCompare(b.date));html+=`<div class="listtoolbar">${[['todos','Todos'],['pendentes','Em andamento'],['concluidos','Concluídos']].map(([k,t])=>`<button data-filter="${k}" class="${filter===k?'active':''}">${t}</button>`).join('')}</div>${panel('Minha lista <span class="tag">'+list.length+'</span>',list.length?list.map(row).join(''):empty(page))}`}$('#view').innerHTML=html}document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.page){page=b.dataset.page;filter='todos';render()}if(b.dataset.add)add(b.dataset.add);if(b.dataset.filter){filter=b.dataset.filter;render()}if(b.dataset.month){month=new Date(month.getFullYear(),month.getMonth()+Number(b.dataset.month),1);render()}if(b.dataset.date){selected=b.dataset.date;if(page==='inicio')page='eventos';render()}if(b.dataset.delete){items=items.filter(i=>i.id!==b.dataset.delete);save()}});document.addEventListener('change',e=>{if(e.target.dataset.done){let i=items.find(i=>i.id===e.target.dataset.done);i.done=e.target.checked;save()}});$('#close').onclick=()=>$('#modal').close();$('#form').onsubmit=e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));items.push({...data,id:crypto.randomUUID(),done:false});save();$('#modal').close()};$('#export').onclick=()=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(items,null,2)],{type:'application/json'}));a.download='meu-espaco.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};window.addEventListener('storage',e=>{if(e.key==='meu-espaco-v1'){try{items=JSON.parse(e.newValue||'[]');render()}catch{}}});render();
